package com.gameaggregator.authservice.domain; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; class AuthUserTest { @Test void locksAfterFiveFailures(){ AuthUser user=new AuthUser("user@example.com","hash","User"); for(int i=0;i<5;i++) user.loginFailed(); assertThat(user.getFailedLoginAttempts()).isEqualTo(5); assertThat(user.isLocked()).isTrue(); user.loginSucceeded(); assertThat(user.isLocked()).isFalse(); } }
